import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Compresser une image est facile. En compresser cinquante est un autre travail, et les faire une par une gaspille un après-midi.</p>\n<p>La compression en lot résout cela. Vous déposez tout un dossier, vous choisissez un préréglage, et vous téléchargez toutes les images compressées ensemble dans un seul fichier ZIP.</p>\n<p>Ce guide explique comment fonctionne le <a href=\"/fr/compresser-images-en-lot/\">compresseur d’images en lot</a>, quand l’utiliser, et comment obtenir des résultats cohérents sur tout un lot.</p>\n<h2 id=\"what-is-bulk-compression\">Qu’est-ce que la compression d’images en lot ?</h2>\n<p>La compression en lot applique les mêmes réglages à beaucoup d’images en une fois. Au lieu d’ouvrir chaque fichier séparément, vous traitez tout l’ensemble en un seul passage.</p>\n<p>L’outil parcourt la file image par image, en affichant une barre de progression en direct. Vous pouvez regarder chaque fichier se terminer et repérer les problèmes au fur et à mesure.</p>\n<p>Chaque image est compressée individuellement. L’outil trouve la meilleure qualité pour chaque fichier, donc un simple portrait et un paysage détaillé reçoivent un traitement différent.</p>\n<p>Les résultats se téléchargent ensemble sous forme de fichier ZIP. Cela garde l’ensemble organisé et prêt à envoyer en une seule fois.</p>\n<p>Pour les blogs, les boutiques et les photothèques, la compression en lot transforme des heures de travail répétitif en quelques minutes d’attente.</p>\n<h2 id=\"how-it-works\">Comment fonctionne le compresseur en lot</h2>\n<p>Déposez vos images dans la zone d’envoi ou sélectionnez tout un dossier. Les fichiers JPG, PNG, WebP et HEIC sont acceptés, et les lots mixtes fonctionnent très bien.</p>\n<p>Choisissez un préréglage : Équilibré, Fichier plus petit, ou Haute qualité. Chaque préréglage définit le point de départ de la qualité et l’approche de compression pour tout le lot.</p>\n<p>L’outil traite la file avec une barre de progression en direct. Vous pouvez voir quels fichiers sont terminés, lesquels sont en cours, et combien de taille totale a été économisée.</p>\n<p>Prévisualisez les résultats individuels avant de télécharger. Cliquez sur n’importe quelle image terminée pour vérifier sa qualité en taille réelle.</p>\n<p>Quand le lot est terminé, cliquez sur Tout télécharger pour obtenir un seul fichier ZIP contenant toutes les images compressées.</p>\n<h2 id=\"presets-explained\">Les trois préréglages expliqués</h2>\n<p>Équilibré est le préréglage par défaut. Il commence à 70 % de qualité et vise un bon juste milieu entre taille de fichier et qualité visuelle.</p>\n<p>Fichier plus petit pousse la compression plus fort. Il produit des fichiers plus légers qui se chargent plus vite, au prix d’une certaine douceur visible.</p>\n<p>Haute qualité privilégie l’aspect visuel plutôt que la taille. Il garde plus de détails et produit des fichiers plus gros, ce qui convient aux portfolios et aux galeries.</p>\n<p>Le préréglage définit le point de départ, pas un résultat fixe. Chaque image est quand même optimisée individuellement dans l’approche du préréglage.</p>\n<p>Commencez par Équilibré pour la plupart des travaux. Passez à Fichier plus petit pour les miniatures et à Haute qualité pour les images vedettes.</p>\n<h2 id=\"when-to-use-bulk\">Quand utiliser la compression en lot</h2>\n<p>Les migrations de blog sont le cas classique. Déplacer cinquante anciennes miniatures vers un nouveau site signifie cinquante compressions, et un lot les gère en quelques minutes.</p>\n<p>Les catalogues de produits en sont un autre. Un lancement saisonnier avec une centaine de photos de produits a besoin d’une compression cohérente sur tout l’ensemble.</p>\n<p>Les photothèques en profitent aussi. Réduire un album de voyage avant de le partager garde le téléchargement rapide pour tous ceux qui le reçoivent.</p>\n<p>Toute tâche répétée convient. Si vous compressez le même type d’image chaque semaine, un préréglage de lot fait gagner du temps à chaque tour.</p>\n<p>Les images uniques n’ont pas besoin du mode en lot. Pour une seule photo, les outils individuels à taille cible en Ko donnent un contrôle plus précis.</p>\n<h2 id=\"batch-vs-target-tools\">Le lot contre les outils à taille cible en Ko</h2>\n<p>Le compresseur en lot fonctionne par préréglage de qualité, pas par taille de fichier exacte. Il rend les images plus petites sans promettre un nombre précis de kilooctets.</p>\n<p>Les outils à taille cible en Ko fonctionnent dans l’autre sens. Ils garantissent qu’un fichier atterrit sous 50 Ko, 100 Ko, 200 Ko ou 500 Ko, grâce à une recherche binaire de qualité.</p>\n<p>Utilisez le mode en lot quand l’objectif est des fichiers généralement plus petits. Utilisez un outil à taille cible en Ko quand un portail ou une plateforme exige une limite exacte.</p>\n<p>Le <a href=\"/fr/compresser-image-a-taille-cible/\">compresseur à taille de fichier cible</a> fait le pont entre les deux. Il compresse les lots vers une taille personnalisée exacte, combinant la commodité du lot et des limites précises.</p>\n<p>Pour l’optimisation web avec préréglages et sortie HTML, l’<a href=\"/fr/optimiser-images-pour-le-web/\">outil d’optimisation des images pour le web</a> est le meilleur outil.</p>\n<h2 id=\"quality-in-batches\">La qualité dans un lot</h2>\n<p>Toutes les images d’un lot n’ont pas besoin du même traitement. Un portrait se compresse facilement, tandis qu’un paysage détaillé demande plus d’attention.</p>\n<p>L’outil gère cela automatiquement. Chaque image reçoit sa propre optimisation, donc le lot reste cohérent sans réglages manuels.</p>\n<p>Prévisualisez d’abord les images les plus difficiles. Une photo détaillée ou une capture d’écran avec du petit texte montrera les problèmes avant un simple portrait.</p>\n<p>Si une image paraît douce, recompressez-la seule avec d’autres réglages. Vous n’avez pas besoin de relancer tout le lot pour un seul fichier.</p>\n<p>Le résumé du lot indique les économies totales. Voir cinquante images passer de 200 Mo à 15 Mo rend le bénéfice concret.</p>\n<h2 id=\"formats-in-batches\">Les formats mixtes dans un seul lot</h2>\n<p>Un lot peut mélanger des photos JPG, des captures PNG et des clichés HEIC de téléphone. L’outil lit chaque format et le gère comme il convient.</p>\n<p>Les PNG transparents demandent de l’attention. Les convertir en JPG remplit l’arrière-plan, généralement en blanc, ce qui peut ne pas convenir aux icônes et aux logos.</p>\n<p>L’outil peut convertir automatiquement les gros PNG en JPG ou WebP. Cette simple option transforme souvent un lot gonflé en un lot propre et léger.</p>\n<p>Les fichiers HEIC des iPhones fonctionnent directement. Envoyez-les tels quels au lieu de les convertir d’abord dans une autre application.</p>\n<p>Les GIF animés n’ont pas leur place dans un lot en vrac. Ils ont besoin du <a href=\"/fr/compresser-gif/\">compresseur GIF</a> dédié, qui gère les images et les palettes.</p>\n<h2 id=\"zip-workflow\">Le téléchargement ZIP, étape par étape</h2>\n<p>Le fichier ZIP contient toutes les images compressées du lot, avec des noms de fichiers qui les identifient comme des copies compressées.</p>\n<p>Extrayez le ZIP dans son propre dossier. Cela garde l’ensemble compressé séparé des originaux et facile à retrouver plus tard.</p>\n<p>Vérifiez quelques fichiers extraits avant de les envoyer où que ce soit. Un aperçu rapide repère le rare mauvais résultat avant sa mise en ligne.</p>\n<p>Renommez clairement les fichiers si les noms automatiques ne sont pas assez descriptifs. Un nom qui inclut l’usage évite la confusion plus tard.</p>\n<p>Gardez les originaux dans leur propre dossier. Le ZIP est un paquet de livraison, et les originaux sont la référence à laquelle vous revenez.</p>\n<h2 id=\"phone-batches\">La compression en lot sur un téléphone</h2>\n<p>Le mode en lot fonctionne sur les téléphones, mais avec des limites. Un téléphone a moins de mémoire qu’un ordinateur portable, donc les très gros lots peuvent être lents.</p>\n<p>Divisez les gros lots en groupes plus petits sur un téléphone. Vingt images à la fois fonctionnent sans accroc, tandis qu’une centaine peut peiner.</p>\n<p>Choisissez les originaux dans votre galerie, pas des copies enregistrées depuis des applications de messagerie. Les messageries réduisent les photos avant même que vous les voyiez.</p>\n<p>Téléchargez le ZIP dans votre application Fichiers et extrayez-le là. Vérifiez les tailles de fichiers avant de les joindre à un e-mail ou à un envoi.</p>\n<p>Pour les plus gros lots, utilisez un ordinateur portable. La démarche est identique, mais la mémoire supplémentaire rend les gros travaux plus rapides.</p>\n<h2 id=\"common-mistakes\">Les erreurs courantes en compression en lot</h2>\n<p>Partir de fichiers déjà compressés est la plus grosse erreur. Chaque cycle de compression ajoute des dégâts, alors utilisez toujours les originaux.</p>\n<p>Choisir le mauvais préréglage fait perdre du temps. Fichier plus petit sur un portfolio donne mauvaise allure au travail, tandis que Haute qualité sur des miniatures gaspille de la bande passante.</p>\n<p>Sauter l’aperçu est courant aussi. Un lot de cinquante peut cacher un mauvais résultat, et une vérification rapide des images les plus difficiles le repère.</p>\n<p>Oublier les originaux est l’erreur la plus coûteuse. Une fois le lot terminé, les originaux sont le seul moyen de revenir à la pleine qualité.</p>\n<p>Enfin, ne mélangez pas les GIF animés dans un lot de photos. Ils ont besoin de leur propre outil et de leurs propres réglages.</p>\n<h2 id=\"privacy-in-bulk\">La confidentialité dans la compression en lot</h2>\n<p>Toute la compression se fait dans votre navigateur. Vos photos sont traitées localement et ne sont jamais envoyées sur un serveur.</p>\n<p>Cela compte pour le travail en lot, qui inclut souvent des photos personnelles, des séances client ou des produits non encore lancés. Rien ne quitte votre appareil.</p>\n<p>Les balises GPS de l’appareil photo et les données EXIF sont supprimées pendant la compression. Les fichiers téléchargés ne gardent aucune trace du lieu ou du moment où ils ont été pris.</p>\n<p>Pour le travail client, cette confidentialité est un atout. Vous pouvez compresser un lot sensible sans vous soucier de qui d’autre pourrait le voir.</p>\n<p>Vérifiez toujours les fichiers téléchargés avant de les partager. La confidentialité du traitement ne remplace pas la prudence dans la diffusion.</p>\n<h2 id=\"batch-summary\">Lire le résumé du lot</h2>\n<p>Quand un lot se termine, l’outil affiche un résumé des économies totales. Il indique la taille totale d’origine, le total compressé et le pourcentage économisé.</p>\n<p>Les lots de photos typiques économisent 80 à 90 %. Un dossier de 200 Mo qui tombe à 20 Mo est un résultat normal, pas une exception.</p>\n<p>Le résumé montre aussi les résultats par fichier. Cherchez tout fichier qui a très peu économisé, car il était peut-être déjà compressé.</p>\n<p>Les fichiers qui ont grossi au lieu de rétrécir méritent de l’attention. L’outil les signale, et la bonne décision est généralement de garder le fichier original.</p>\n<p>Partagez les chiffres du résumé avec votre équipe. Des économies concrètes plaident mieux pour la compression en lot que n’importe quel argument.</p>\n<h2 id=\"recompress-single\">Recompresser une seule image récalcitrante</h2>\n<p>Chaque grand lot a une image récalcitrante. Un fichier ressort doux, ou manque la qualité attendue, tandis que les autres ont bonne allure.</p>\n<p>Ne relancez pas tout le lot. Sortez ce fichier et compressez-le seul avec d’autres réglages.</p>\n<p>Essayez d’abord le préréglage Haute qualité. Une image récalcitrante a souvent juste besoin d’une touche plus douce que celle donnée par le préréglage du lot.</p>\n<p>Si le format est le problème, changez-le. Une photo PNG recompressée en JPG passe souvent d’un échec à un résultat propre.</p>\n<p>Remplacez le mauvais fichier dans l’ensemble ZIP par la nouvelle version. Le lot reste intact, et seul le fichier problématique change.</p>\n<h2 id=\"dimension-consistency\">Garder des dimensions cohérentes dans un lot</h2>\n<p>Le compresseur en lot garde les dimensions d’origine, donc un lot de tailles mixtes reste mixte. Cela peut paraître désordonné sur une page de blog ou de boutique.</p>\n<p>Redimensionnez d’abord si la cohérence compte. Passez les images dans le redimensionneur avec une largeur commune, puis compressez l’ensemble redimensionné.</p>\n<p>Pour les catalogues de produits, des dimensions cohérentes sont essentielles. Une grille de tailles mixtes paraît peu professionnelle, aussi bonne que soit la compression.</p>\n<p>Pour les miniatures de blog, le thème recadre souvent les images automatiquement. Vérifiez comment le thème gère les tailles mixtes avant de décider de redimensionner.</p>\n<p>Planifiez les dimensions avant le lot. Quelques minutes de planification évitent une nouvelle exécution plus tard.</p>\n<h2 id=\"backup-strategy\">Une stratégie de sauvegarde pour les lots</h2>\n<p>Chaque lot devrait avoir un plan de sauvegarde. Les originaux sont la sauvegarde, et les perdre transforme un travail réversible en perte permanente.</p>\n<p>Gardez les originaux dans au moins deux endroits. Un dossier local plus un lecteur cloud protège contre un ordinateur portable perdu ou un disque dur en panne.</p>\n<p>Gardez le ZIP compressé comme sauvegarde secondaire. Ce n’est pas un remplacement des originaux, mais il évite de relancer le lot.</p>\n<p>Étiquetez les sauvegardes par date et travail. Un dossier nommé originaux-lot-blog-2026-11 est retrouvable des années plus tard ; un dossier nommé divers ne l’est pas.</p>\n<p>Testez la sauvegarde de temps en temps. Une sauvegarde que vous n’avez jamais restaurée est un espoir, pas un plan.</p>\n<h2 id=\"seasonal-batches\">Les lots saisonniers pour les boutiques et les blogs</h2>\n<p>Les boutiques et les blogs font des lots saisonniers. Une nouvelle collection ou un article de fête signifie des dizaines d’images qui ont besoin du même traitement.</p>\n<p>Construisez un processus répétable pour le travail saisonnier. Le même préréglage, le même nommage et la même structure de dossiers à chaque fois.</p>\n<p>Gardez les originaux de la saison dernière. Ils reviennent souvent dans un nouveau contexte, et recompresser à partir des originaux vaut mieux que réutiliser d’anciennes copies compressées.</p>\n<p>Revoyez le préréglage chaque saison. Un préréglage qui convenait à la conception de l’an dernier peut ne pas convenir à la mise en page ou aux tailles d’images de cette année.</p>\n<p>Les lots saisonniers sont là où la compression en lot se rentabilise. Le temps gagné sur quatre saisons se mesure en jours, pas en minutes.</p>\n<h2 id=\"accessibility-batches\">L’accessibilité dans le travail en lot</h2>\n<p>Les images compressées doivent quand même servir chaque visiteur. Un lot qui produit des images douces et peu contrastées échoue pour les lecteurs qui voient mal.</p>\n<p>Vérifiez le contraste dans les images les plus difficiles. Les textes superposés et les petites étiquettes doivent rester lisibles après compression.</p>\n<p>Ajoutez toujours du texte alternatif aux images en lot. Une image compressée avec un bon texte alternatif sert plus de gens qu’une image parfaite sans texte alternatif.</p>\n<p>Gardez les visages et les sujets clés nets. Un préréglage de lot qui adoucit trop les visages doit être ajusté, même si les tailles de fichiers ont bonne allure.</p>\n<p>La compression et l’accessibilité vont ensemble. Une source claire et contrastée se compresse mieux et est plus facile à lire pour chaque spectateur.</p>\n<h2 id=\"final-check\">Une dernière vérification avant l’envoi</h2>\n<p>Ouvrez trois images au hasard du lot terminé en taille réelle. Si elles paraissent propres, le lot est bon ; si l’une paraît douce, vérifiez le reste avant l’envoi.</p>\n<p>Confirmez que le ZIP s’est extrait correctement et que le nombre de fichiers correspond au lot d’origine. Un fichier manquant maintenant est plus facile à corriger qu’une image manquante sur une page en direct.</p>\n<p>Pour les étapes pratiques, lisez <a href=\"/fr/blog/comment-compresser-plusieurs-images-a-la-fois/\">Comment compresser plusieurs images à la fois</a>. Pour les bonnes pratiques de lot, consultez <a href=\"/fr/blog/compression-images-par-lots-bonnes-pratiques/\">Compression d’images par lots : export ZIP et bonnes pratiques</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Combien d’images puis-je compresser dans un seul lot ?","answer":"Il n’y a pas de limite fixe de nombre de fichiers ni de quota quotidien. Les lots de dizaines d’images fonctionnent bien sur un ordinateur portable. Sur un téléphone à mémoire limitée, les très gros lots de fichiers énormes peuvent être plus lents, alors divisez-les en groupes plus petits si besoin."},{"question":"La compression en lot redimensionne-t-elle mes images ?","answer":"Non, le compresseur en lot garde les dimensions originales en pixels et ne réduit la taille du fichier que par la compression de qualité. Si vous avez aussi besoin de dimensions plus petites, utilisez d’abord le redimensionneur d’images, puis compressez les fichiers redimensionnés en lot."},{"question":"Quelle est la différence entre les trois préréglages de lot ?","answer":"Équilibré commence à 70 % de qualité pour un bon juste milieu. Fichier plus petit pousse la compression plus fort pour des fichiers plus légers. Haute qualité garde plus de détails pour les portfolios et les galeries. Chaque image est quand même optimisée individuellement dans le préréglage choisi."},{"question":"Puis-je ajouter d’autres images après la fin d’un lot ?","answer":"Oui, vous pouvez ajouter des photos supplémentaires à la file après la fin du premier lot. Les nouveaux fichiers sont traités avec les mêmes réglages, et vous pouvez tout télécharger ensemble quand les nouveaux éléments sont terminés."},{"question":"Pourquoi une image de mon lot a-t-elle affiché un avertissement indiquant qu’elle avait grossi ?","answer":"Un fichier peut grossir quand il est réencodé dans un format qui lui convient mal, généralement un petit PNG déjà fortement compressé. L’outil vous avertit au lieu de vous remettre silencieusement un fichier plus gros. Laissez ce fichier tel quel ou essayez un autre format."},{"question":"Puis-je compresser des GIF animés dans un lot en vrac ?","answer":"Non, les GIF animés ont besoin du compresseur GIF dédié, qui gère les fréquences d’images et les palettes de couleurs. Déposer un GIF dans un lot de photos ne compressera pas son animation correctement. Utilisez l’outil GIF pour les animations et l’outil en lot pour les images fixes."}];
